class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    PlatformRequest<false> platformsMinimal() const {
        return PlatformRequest<false>(binding_.get(), true);
    }

    PlatformRequest<false> platforms() const {
        return PlatformRequest<false>(binding_.get());
    }

    PlatformRequest<false> platformsWithChildren() const {
        return PlatformRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    SampleRecordRequest<false> sampleRecordsMinimal() const {
        return SampleRecordRequest<false>(binding_.get(), true);
    }

    SampleRecordRequest<false> sampleRecords() const {
        return SampleRecordRequest<false>(binding_.get());
    }

    SampleRecordRequest<false> sampleRecordsWithChildren() const {
        return SampleRecordRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    SampleLinkRequest<false> sampleLinksMinimal() const {
        return SampleLinkRequest<false>(binding_.get(), true);
    }

    SampleLinkRequest<false> sampleLinks() const {
        return SampleLinkRequest<false>(binding_.get());
    }

    SampleLinkRequest<false> sampleLinksWithChildren() const {
        return SampleLinkRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
